use rivet::{adaptive,domain::*,scheduler::*,model_pool::*};
fn configured(roles:usize,initial:Mode)->State{let p=Profile{id:"shared".into(),provider:rivet::config::ProviderConfig{profile:"llama.cpp-compatible".into(),endpoint:"http://127.0.0.1:1/v1/chat/completions".into(),model:"synthetic".into(),context_tokens:Some(65536)},instance:"actual-one".into(),resident:true,remote:false,weights_ram:128<<20,weights_vram:0,kv_ram_per_token:16,kv_vram_per_token:0,slots:1,loading_ram:64<<20,loading_vram:0,qualification:None};State::new(Policy{adaptive:Some(adaptive::Policy{initial,allowed:vec![Mode::Solo,Mode::Pair,Mode::Crew,Mode::Fleet,Mode::Mesh],agent_ceiling:8,coordination:Some(false),review:Some(false),director:Some(false),tokens_per_actor:1,steps_per_actor:1,cost_per_actor:0,max_transitions:2,role_profiles:vec![],mesh_peers:2}),schema_version:1,behavior:Behavior::Shared,limits:Limits{ram:2<<30,vram:0,os_ram:256<<20,tools_ram:1<<30,browser_ram:0,loading_overlap_ram:32<<20,loading_overlap_vram:0},profiles:vec![p],assignments:vec!["shared".into();roles],phases:vec![]},1,roles,5).unwrap()}
#[test]
fn smallest_valid_quiescent_composition_preserves_scope_and_rejects_ambiguity_revocation_and_budget(){
    let mut graph=Graph::new(template(Mode::Pair,"same immutable scope",vec!["code".into()]).unwrap()).unwrap();let root=graph.next(1).unwrap();let claim=graph.claim(root,1,1,100,1).unwrap();assert!(adaptive::derive(&graph,Mode::Solo,2).is_err());graph.finish(&claim,1,true,None).unwrap();let model=configured(2,Mode::Pair);let (next,assignment)=adaptive::choose(&graph,&model,100,100,0).unwrap().unwrap();assert_eq!(next.plan.mode,Mode::Solo);assert_eq!(next.plan.agents.len(),1);assert_eq!(assignment.len(),1);for(old,new)in graph.nodes.iter().zip(&next.nodes){assert_eq!(old.task.id,new.task.id);assert_eq!(old.task.description,new.task.description);assert_eq!(old.task.writes,new.task.writes);assert_eq!(old.task.criterion,new.task.criterion);}
    let mut ambiguous=model.clone();ambiguous.policy.adaptive.as_mut().unwrap().coordination=None;assert!(adaptive::choose(&graph,&ambiguous,100,100,0).unwrap().is_none());let mut revoked=model.clone();revoked.policy.adaptive.as_mut().unwrap().allowed.clear();assert!(adaptive::choose(&graph,&revoked,100,100,0).unwrap().is_none());assert!(adaptive::choose(&graph,&model,0,0,0).is_err());let mut constrained=model.clone();constrained.policy.adaptive.as_mut().unwrap().coordination=Some(true);assert!(adaptive::choose(&graph,&constrained,100,100,0).unwrap().is_none());
    let mut fleet=Graph::new(template(Mode::Fleet,"review remains mandatory",vec!["code".into()]).unwrap()).unwrap();let root=fleet.next(1).unwrap();let claim=fleet.claim(root,1,1,100,1).unwrap();fleet.finish(&claim,1,true,None).unwrap();let mut model=configured(4,Mode::Fleet);let policy=model.policy.adaptive.as_mut().unwrap();policy.coordination=Some(true);policy.review=Some(true);let(next,_)=adaptive::choose(&fleet,&model,100,100,0).unwrap().unwrap();assert_eq!(next.plan.mode,Mode::Crew);assert_eq!(next.plan.agents.len(),3);assert!(next.nodes.iter().any(|n|matches!(n.task.kind,Kind::Review{..})));assert!(next.plan.validate().is_ok());
}
#[test]
fn mesh_peer_count_deterministic_ties_and_single_owner_survive_yields(){
    assert!(mesh_template("scope",vec![],0).is_err());assert!(mesh_template("scope",vec![],33).is_err());let plan=mesh_template("scope",vec![],3).unwrap();let mut graph=Graph::new(plan).unwrap();let root=graph.next(1).unwrap();let c=graph.claim(root,1,1,100,1).unwrap();graph.finish(&c,1,true,None).unwrap();for _ in 0..1000{let id=graph.next(1).unwrap();let expected=graph.claim_actor(id).unwrap();let claim=graph.claim(id,1,1,100,2).unwrap();assert_eq!(claim.actor,expected);assert!(graph.validate_claim(&Claim{actor:ActorId::default(),..claim.clone()},1).is_err());graph.yield_step(&claim,1).unwrap();assert!(graph.validate_claim(&claim,1).is_err());assert_eq!(graph.node(id).unwrap().task.actor,expected);}assert_eq!(graph.plan.agents.len(),3);assert!(graph.nodes.iter().filter(|n|n.task.kind==Kind::Coding).all(|n|n.fence>=333));
}
